impl Movie {
    fn charge(&self, days_rented: u32) -> f64 {
        let mut result = 0.0;
        match self.price_code {
            0 => {
                result += 2.0;
                if days_rented > 2 {
                    result += (days_rented - 2) as f64 * 1.5;
                }
            }
            1 => result += days_rented as f64 * 3.0,
            _ => {}
        }
        result
    }
}
